update pages set contenu = '{"sections":[{"type":"heros","h1":"Maintenance industrielle à Besançon et dans le Doubs","mecanisme":"L''horlogerie bisontine a laissé une culture du micron : microtechnique, décolletage, outillage de précision, puis les lignes de dispositifs médicaux et d''implants autour de Temis. Plus loin, vers Sochaux et Montbéliard, la mécanique lourde de l''automobile impose un tout autre rythme. Nos techniciens itinérants couvrent le Doubs et se déplacent partout en France.","cta":"Demander une intervention à Besançon","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. L''astreinte 24/24 et 7/7 couvre les nuits, les week-ends et les jours fériés."},{"type":"chiffres","chiffres":[{"valeur":"+ 100","libelle":"collaborateurs, mécaniciens, électriciens, automaticiens, roboticiens"},{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, résultats partagés"},{"valeur":"+ 120","libelle":"clients accompagnés, dont plus de 80 réguliers"}]},{"type":"probleme","punchline":"Un centre d''usinage décroche de quelques microns. Rien ne s''arrête, et pourtant chaque pièce qui sort part au rebut.","puces":[{"accroche":"En précision, la dérive se voit dans la pièce avant l''alarme.","texte":"Un défaut de machine qui ne déclenche rien coûte une série entière."},{"accroche":"Le médical ne tolère aucune improvisation.","texte":"Traçabilité, propreté, régularité : une intervention non documentée pose un problème de conformité."},{"accroche":"Le décolletage vit de machines très spécifiques.","texte":"Presses de découpage, commandes numériques anciennes : peu de gens savent encore les régler."},{"accroche":"Le bassin recrute les mêmes profils que l''automobile voisine.","texte":"Entre Besançon et Sochaux, vos annonces de technicien attendent."},{"accroche":"La filière comté et le bois travaillent en saison.","texte":"Une ligne de conditionnement arrêtée pendant la charge se paie en matière perdue."}]},{"type":"offre","lignes":[{"prestation":"**Maintenance des machines de précision** : centres d''usinage, presses, commandes numériques, réglages et reprise de jeux.","benefice":"La pièce sort dans la tolérance, et le rebut redescend."},{"prestation":"**Interventions documentées** pour les lignes médicales : propreté, traçabilité, habilitations à jour.","benefice":"Vos audits trouvent une trace écrite pour chaque passage."},{"prestation":"**Dépannage sur site** avec recherche de cause racine, du moteur à l''armoire électrique.","benefice":"Le même défaut ne revient pas sous un autre nom le mois suivant."},{"prestation":"**Préventif planifié** sur vos heures de fonctionnement réelles, resserré avant les saisons de charge.","benefice":"Les révisions tombent quand la machine est disponible, pas quand elle casse."},{"prestation":"**Automatisme et rétrofit** : SIEMENS et Schneider, variation de vitesse, supervision, roboticiens ABB et Fanuc.","benefice":"Une commande numérique ancienne retrouve un pilotage fiable sans remplacement."},{"prestation":"**Domaines combinés** : [mécanique](/expertises/mecanique/), [électrique](/expertises/electrique/), [hydraulique](/expertises/hydraulique/), [pneumatique](/expertises/pneumatique/), [soudure](/expertises/soudure/).","benefice":"Un seul interlocuteur pour un défaut qui traverse plusieurs spécialités."},{"prestation":"**Astreinte 24/24 et 7/7 en option**, mobilisation de techniciens mobiles partout en France.","benefice":"Un arrêt du week-end ne devient pas un lundi de production perdu."},{"prestation":"**Technicien en [Résidence](/offres/residence/)** intégré à votre équipe, prise de poste en 2 à 3 semaines.","benefice":"Le poste que le bassin ne vous permet pas de pourvoir est tenu, remplacement assuré."}],"prose":[{"texte":"Pour une mise en service, un transfert de ligne ou une extension d''atelier, notre offre [chantier](/offres/chantier/) prend le relais avec un chef de projet unique."}]},{"type":"deroule","etapes":[{"titre":"Premier contact","texte":"vous décrivez la panne ou le besoin. Un chargé d''affaires rappelle dans l''heure aux horaires ouvrés."},{"titre":"Qualification","texte":"machines, tolérances attendues, accès au site, habilitations, contraintes de propreté. Tout se note avant le chiffrage."},{"titre":"Devis écrit","texte":"périmètre, créneaux, matériel, conditions horaires. L''exceptionnel se chiffre en amont."},{"titre":"Intervention","texte":"accueil sécurité, plan de prévention, consignation, diagnostic, réparation, contrôle après remise en route."},{"titre":"Compte rendu","texte":"opérations, mesures, temps passé, pièces, préconisations, versés dans votre GMAO."},{"titre":"Suivi","texte":"sur contrat, revue de la récurrence par équipement et du respect du plan préventif."}]},{"type":"garanties","puces":[{"accroche":"Le profil vous est présenté avant l''intervention.","texte":"Entretien technique et comportemental, 10 % des candidats retenus, résultats d''évaluation partagés. Vos machines ne servent pas de terrain d''apprentissage."},{"accroche":"Chaque passage laisse des mesures, pas des impressions.","texte":"Contrôle après remise en route, compte rendu chiffré, historique versé dans votre outil."},{"accroche":"Un périmètre et une sortie écrits.","texte":"Inclus, exclu, conditions d''astreinte, conditions d''arrêt du contrat."}]},{"type":"cta","question":"Besoin de ramener une machine dans ses tolérances ?","bouton":"Demander une intervention à Besançon","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Un technicien à temps plein sur un site de pièces mécaniques de précision","texte":", centres d''usinage, presses et commandes numériques, en 2025","lienLibelle":"Étude de cas VOIT : site du Grand Est","lienHref":"/preuves/voit-grand-est/"},{"titre":"18 à 25 techniciens mobilisés sur plusieurs sites du Grand Est","texte":", pour accompagner la bascule vers le véhicule électrique","lienLibelle":"Étude de cas STELLANTIS : sites du Grand Est","lienHref":"/preuves/stellantis-grand-est/"},{"titre":"Techniciens présents au quotidien sur les équipements critiques d''un fabricant de composants techniques","texte":", depuis 2025","lienLibelle":"Étude de cas JTEKT : maintenance des installations","lienHref":"/preuves/jtekt/"},{"titre":"Un automaticien SIEMENS affecté au démarrage d''une nouvelle ligne de production","texte":", en contexte de montée en charge","lienLibelle":"Étude de cas MERSEN : nouvelles lignes","lienHref":"/preuves/mersen/"}]},{"type":"objections","questions":[{"question":"Intervenez-vous vraiment à Besançon, alors que votre siège est à Lyon ?","reponse":"Oui. Nous n''avons pas d''agence dans le Doubs et nous ne l''inventons pas : nos techniciens se déplacent partout en France et interviennent sur site. Votre demande est rappelée dans l''heure aux horaires ouvrés, et le chargé d''affaires vous dit si le besoin est tenable."},{"question":"Quelles communes couvrez-vous ?","reponse":"Besançon et la zone de Temis, École-Valentin et le Grand Besançon, avec l''axe vers Montbéliard et Sochaux. Au-delà, nos techniciens se déplacent partout en France."},{"question":"Savez-vous intervenir sur des machines de précision et du décolletage ?","reponse":"Le premier passage sert d''état des lieux : jeux, alignements, états de surface, réglages. Si une spécialité manque, le chargé d''affaires le dit au lieu d''envoyer quelqu''un au hasard."},{"question":"Vos techniciens travaillent-ils sur des lignes de dispositifs médicaux ?","reponse":"Oui, avec les habilitations et les règles du site. Chaque intervention est documentée, propreté et traçabilité comprises. Le point se fait à la qualification, jamais une fois sur place."},{"question":"Pouvez-vous détacher un technicien dans notre atelier ?","reponse":"Oui, en résidence : technicien intégré à votre équipe, encadré par un référent technique Migen, opérationnel en 2 à 3 semaines. Absence ou départ, un profil équivalent arrive briefé sur vos machines."},{"question":"Combien coûte un contrat de maintenance ?","reponse":"L''offre Zéro arrêt fonctionne en abonnement, trois niveaux de couverture, sur devis, engagement type 6 mois renouvelable, diagnostic gratuit au départ."}]},{"type":"ctaFinal","question":"Besoin de fiabiliser un parc de précision avant la prochaine série ?","bouton":"Demander une intervention à Besançon","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]}'::jsonb where path = '/implantations/maintenance-industrielle-besancon/';
